// ===== One-off codegen: turn src/data/redirects.ts into real .astro pages =====
// Run with:  node scripts/gen-redirects.mjs   (or `npm run gen:redirects`)
//
// GitHub Pages has no server-side redirect support, so each old WordPress URL
// needs a real published HTML page. This script writes one tiny .astro file per
// redirect entry. Safe to re-run — it only overwrites files it owns (every
// generated file starts with the AUTO-GENERATED marker). Commit the generated
// files so the redirect pages ship with every build.

import { readFileSync, writeFileSync, mkdirSync, readdirSync, unlinkSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const redirectsSrc = readFileSync(join(ROOT, "src", "data", "redirects.ts"), "utf8");

// Parse { from: "...", to: "..." } entries. The source file is hand-maintained
// and each entry lives on one line, so a line-based scan is robust and avoids a
// TypeScript toolchain dependency.
const redirects = [];
for (const line of redirectsSrc.split("\n")) {
  const m = line.match(/\{\s*from:\s*"([^"]+)"\s*,\s*to:\s*"([^"]+)"\s*\}/);
  if (m) redirects.push({ from: m[1], to: m[2] });
}
if (!redirects.length) {
  console.error("No redirect entries found in src/data/redirects.ts");
  process.exit(1);
}

const pagesDir = join(ROOT, "src", "pages");
const MARKER = "AUTO-GENERATED by scripts/gen-redirects.mjs";

// Clean up previously generated redirect files so removed entries don't linger.
// Walk src/pages recursively; any .astro file containing the AUTO-GENERATED
// marker is one we own and can safely delete before regenerating.
function cleanupGenerated(dir) {
  for (const name of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, name.name);
    if (name.isDirectory()) {
      cleanupGenerated(full);
    } else if (name.name.endsWith(".astro")) {
      if (readFileSync(full, "utf8").includes(MARKER)) unlinkSync(full);
    }
  }
}
cleanupGenerated(pagesDir);

let written = 0;
for (const { from, to } of redirects) {
  const outFile = join(pagesDir, `${from}.astro`);
  const fileDir = dirname(outFile);
  mkdirSync(fileDir, { recursive: true });
  const relLayout = relative(fileDir, join(ROOT, "src", "layouts", "Redirect.astro"))
    .split("\\").join("/");
  const relSite = relative(fileDir, join(ROOT, "src", "data", "site.ts"))
    .split("\\").join("/");
  const oldPath = "/" + from.replace(/\/index$/, "") + "/";
  const body = `---
// ${MARKER} — do not edit by hand.
// Source of truth: src/data/redirects.ts
// Old WordPress URL: ${oldPath}  ->  ${to}
import Redirect from "${relLayout}";
import { asset } from "${relSite}";
---
<Redirect to={asset(${JSON.stringify(to)})} />
`;
  writeFileSync(outFile, body);
  written++;
}
console.log(`Wrote ${written} redirect page(s) under src/pages/.`);
